                    <motion.li variants={itemVariants} style={item}>
                        Test
                    </motion.li>
                    <motion.li variants={itemVariants} style={item}>
                        Test
                    </motion.li>
                </motion.ul>
            )}
        </AnimatePresence>
    )
}

